('44b39dae-7a25-5a65-b615-96f25701b058', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Qual assinatura inicia um aplicativo Java clássico?', '["public static void main(String[] args).","private main(String[] args).","static int start(String args).","public void main().","public static main()."]'::jsonb, 0, 'A JVM procura a assinatura convencional do ponto de entrada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.2, páginas 63–67 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3948cbf6-9509-5c4e-b373-d5b20aa8b22c', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Qual extensão identifica normalmente o código-fonte Java?', '[".sql.",".jar apenas.",".exe obrigatoriamente.",".class.",".java."]'::jsonb, 4, 'Arquivos .class contêm o resultado da compilação, não o fonte.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.2, páginas 63–67 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7b88ed6b-bdff-58e8-ba7c-5d2894a022a9', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Uma classe pública chamada Relatorio deve estar normalmente em:', '["Main.txt.","Qualquer arquivo .sql.","relatorio.class como fonte.","Relatorio.exe.","Relatorio.java."]'::jsonb, 4, 'O nome do arquivo-fonte acompanha o da classe pública.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.2, páginas 63–67 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d44ca43f-81d0-568e-8818-a5228d343ced', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Fácil', 'Java diferencia `saldo` de `Saldo`?', '["Somente em comentários.","Não, ignora maiúsculas.","Sim, são identificadores distintos.","Apenas em pacotes externos.","Somente em strings."]'::jsonb, 2, 'A linguagem distingue maiúsculas e minúsculas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.2, páginas 63–67 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3a46e1db-6075-5b57-ac52-05e8d730a964', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Fácil', 'Qual trecho é um comentário de linha Java?', '["`** observação`.","`# observação`.","`-- observação`.","`// observação`.","`<!-- observação -->`."]'::jsonb, 3, 'O comentário // termina no final da linha.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.2, páginas 63–67 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f0b2ba8d-7d0e-5d9a-8d4b-59ce9568af43', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Fácil', 'Qual chamada acrescenta uma quebra de linha ao texto?', '["String.length.","Math.abs.","System.out.println.","System.out.print.","Scanner.nextInt."]'::jsonb, 2, 'println encerra a linha após imprimir seu argumento.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.3, páginas 68–69 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3327e625-8bfe-5933-a952-b82f9e0af00d', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Fácil', 'O que `System.out.print("A"); System.out.print("B");` imprime?', '["A B.","A e B em linhas distintas.","BA.","AB.","Erro de compilação."]'::jsonb, 3, 'print não insere separador nem quebra de linha automaticamente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.3, páginas 68–69 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('13e248e4-c8dc-5b82-93b4-4f2c454d9f02', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Fácil', 'Qual especificador de printf corresponde a inteiro decimal?', '["%d.","%n.","%b.","%f.","%s apenas."]'::jsonb, 0, 'O especificador precisa ser compatível com o argumento.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.4, páginas 70 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('691eade3-bf74-5274-9b4e-4096158e8510', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Fácil', 'Qual especificador de printf representa separador de linha da plataforma?', '["%c.","%d.","%x.","%f.","%n."]'::jsonb, 4, '%n evita fixar uma convenção específica de quebra de linha.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.4, páginas 70 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('866e4063-af15-5890-bdef-faa20b90c094', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Fácil', 'Qual pacote contém Scanner?', '["java.util.","java.awt.","javax.swing.","java.lang apenas.","java.sql."]'::jsonb, 0, 'Scanner pode analisar tokens recebidos de diferentes fontes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.5, páginas 71–74 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('27edc1eb-51bd-5968-a0dc-224d79bb8c20', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Fácil', 'Qual método Scanner lê um próximo token inteiro?', '["nextLineInt().","parseNext().","nextInt().","intValue().","readInteger()."]'::jsonb, 2, 'nextInt interpreta o token conforme as regras do Scanner.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.5, páginas 71–74 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('de76cb3d-9b15-5c1a-9c41-08a93d1388d6', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Fácil', 'Qual importação é implícita em arquivos Java?', '["java.util.","java.lang.","javax.swing.","java.sql.","java.awt."]'::jsonb, 1, 'String e System estão em java.lang.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.5, páginas 71–74 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4430eb3c-ebfc-5286-b79f-06abad644a10', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Fácil', 'Qual valor resulta de `17 / 5` com operandos int?', '["4.","Erro.","3.4.","3.","2."]'::jsonb, 3, 'A divisão inteira descarta a parte fracionária, truncando em direção a zero.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.7, páginas 76–77 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6cff530d-8ddd-5876-90e5-0284a01b8675', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Fácil', 'Qual valor resulta de `17 % 5`?', '["0.","5.","3.","2.","3.4."]'::jsonb, 3, 'O operador % fornece o resto da divisão inteira nesse caso.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.7, páginas 76–77 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bdd4f89a-2f12-5309-8ffc-7cdf02b41556', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Fácil', 'Qual valor resulta de `2 + 3 * 4`?', '["14.","20.","11.","24.","9."]'::jsonb, 0, 'A multiplicação tem precedência sobre a adição.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.7, páginas 76–77 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8fb1fb89-3997-54d9-81f5-c7cdf9a73032', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Fácil', 'Qual valor resulta de `(2 + 3) * 4`?', '["14.","9.","11.","24.","20."]'::jsonb, 4, 'Parênteses determinam a avaliação da soma antes da multiplicação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.7, páginas 76–77 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a4b7bc00-5514-5e59-b648-923136f04c09', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Fácil', 'Após `int a=7; int b=a; a=9;`, qual é b?', '["Indefinido.","7.","0.","9.","16."]'::jsonb, 1, 'Atribuir um primitivo copia seu valor; não cria vínculo entre variáveis.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.7, páginas 76–77 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3787658d-870b-5832-92b3-bc02c11876e9', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Fácil', 'Qual operador testa igualdade entre dois valores int?', '[":=.","==.","equals como operador.","=>.","=."]'::jsonb, 1, 'O sinal simples realiza atribuição, não comparação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.8, páginas 78–81 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e6fe998f-e4e5-51cd-9cc3-e64ac1f27b08', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Fácil', 'Em Java, a condição de um if deve possuir tipo:', '["Qualquer objeto.","char obrigatoriamente.","boolean.","String obrigatoriamente.","int obrigatoriamente."]'::jsonb, 2, 'Java não interpreta automaticamente um inteiro como condição booleana.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.8, páginas 78–81 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a940f3a5-06af-50f7-a788-4a411815dfbe', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Fácil', 'Um ponto e vírgula logo após `if (teste)` pode:', '["Tornar teste sempre verdadeiro.","Criar uma instrução vazia como corpo do if.","Ser sempre um erro léxico.","Eliminar a avaliação de teste.","Executar obrigatoriamente o bloco seguinte só se teste for verdadeiro."]'::jsonb, 1, 'O bloco seguinte pode ficar fora do controle do if.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 2, seção 2.8, páginas 78–81 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
